"""seed real village data for AP mandals with a confident official match

Revision ID: 3d61e7bd3ba9
Revises: b7c8d9e0f1a2
Create Date: 2026-08-27 00:00:00.000000

REAL DATA, sourced live from the Andhra Pradesh government's own "AP CODES"
portal (codes.ap.gov.in), specifically its Revenue Village Codes page's
underlying JSON API (POST codes.ap.gov.in/Gad/Locations/Mandal and
.../RevenueVillages - the same endpoints the public page itself calls via
client-side AJAX, with the credentials embedded in that page's own JS).
This is the official Local Government Directory-style revenue-village
list (English + Telugu name, Revenue Code) per mandal - a materially
better source than Wikipedia scraping, and the source this project should
prefer going forward for any further location master data.

IMPORTANT - two real complications, disclosed rather than silently
resolved, per this project's standing no-fabrication rule:

1. NOT EVERY OFFICIAL MANDAL MAPS CLEANLY ONTO THIS PROJECT'S EXISTING
   `mandals` TABLE (687 rows, seeded by c1a2b3d4e5f6 from Wikipedia).
   Fetching the official mandal list for all 26 districts returned 711
   named mandals (705 distinct names + name-normalization artifacts) vs
   this table's 687 - a real, independently-confirmed discrepancy, not a
   fetch bug:
     - Most differences are transliteration spelling variants (e.g.
       official "Chintapalle" vs this table's "Chinthapalli", official
       "Devarapalle" vs "Devarapalli") - resolved automatically via a
       Levenshtein-distance fuzzy match (threshold: distance <= 25% of
       normalized name length, unique best candidate only, scoped to the
       correct district) run once, offline, against a live snapshot of
       both sides - NOT re-derived at migration time.
     - Some are genuine STRUCTURAL differences the fuzzy match correctly
       refuses to resolve: this table splits some mandals the official
       source does not (Guntur -> "Guntur East"/"Guntur West", Anantapur/
       Chittoor/Kakinada/Kurnool/Nandyal/Ongole/Vizianagaram similarly
       split into Rural/Urban or East/West) - the official API returns
       villages per its own single mandal code, with no way to tell which
       village belongs to which half of this table's split, so these
       mandals are left without village data rather than guessed.
     - Visakhapatnam's own official mandal list is itself stale: it still
       lists the tribal-agency mandals (Araku Valley, Paderu, Chintapalle,
       etc.) that moved to the new Alluri Sitharama Raju district in the
       2022 reorganization - this table already correctly files them
       under ASR (per c1a2b3d4e5f6), so none of Visakhapatnam's official
       mandals match this table's 11 Visakhapatnam rows, and Visakhapatnam
       gets no village data this pass.
     - A handful of official mandals fuzzy-matched to the SAME table row
       (e.g. two similarly-spelled official mandals both nearest to one
       existing mandal) - resolved by keeping only the closer match and
       treating the other as unmatched, rather than merging two distinct
       administrative areas' villages into one mandal.
   Net result: 633 of this table's 687 mandals (92%) received real
   village data covering 633/711 (89%) of the official mandal list; the
   remaining 54 mandals in this table (the Rural/Urban/East/West splits,
   all 11 Visakhapatnam mandals, and ~a dozen names too different to
   safely auto-match, e.g. "Cuddapah" for the now-renamed "Kadapa") are
   left with zero villages, same as they are today - not silently
   patched with a guess. The full match/skip decision list from that
   offline pass is preserved in this project's own working notes, not
   embedded here to keep this file to the data actually being inserted.

2. These are REVENUE villages (the land-administration unit AP CODES
   itself calls "Revenue Village Codes"), not Census villages - the
   two lists differ somewhat in practice (a revenue village can be an
   uninhabited administrative unit, and Census sometimes further splits
   or merges revenue villages for enumeration purposes). Revenue villages
   are the more appropriate choice for a farm-registration app tied to
   land records, and are what this migration seeds - disclosed as a
   provenance choice, not presented as equivalent to Census village
   counts anyone might separately look up.

15,886 real village rows across 633 mandals, English names only (each
official name's Telugu-script parenthetical was stripped; genuine ASCII
qualifier suffixes such as "(R)"/"(U)"/"(CT)"/"(East)"/"(Part)" that
distinguish same-named revenue villages were kept, title-cased for
consistency with this table's other rows). Idempotent by design (ON
CONFLICT ON CONSTRAINT uq_village_mandal_name DO NOTHING), matching the
exact pattern established by 8bf7b0c379d4/c1a2b3d4e5f6 - safe to re-run.
"""
